{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A softer approach to steadying the day</title>
  <meta name="description" content="Holistic and integrative wellness guidance with practical phases and micro-habits. Educational and supportive—no medical guarantees.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <div class="page-wrap">
    <header class="site-header">
      <div class="brand">
        <div class="logo">
          <svg width="48" height="48" viewBox="0 0 48 48" aria-hidden="true">
            <rect x="0" y="0" width="48" height="48" rx="8" fill="#EFE8E1"></rect>
            <circle cx="24" cy="18" r="6" fill="#C9B4A6"></circle>
            <path d="M8 36c6-8 14-8 32-8" stroke="#B89A8C" stroke-width="2" fill="none" stroke-linecap="round"></path>
          </svg>
        </div>
        <div class="identity">
          <div class="name">{{BUSINESS_NAME}}</div>
          <div class="tag">A gentle map for returning to rhythm</div>
        </div>
      </div>
      <nav class="nav">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Conditions</a>
        <a href="approach.html">Approach</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">About</a>
        <a href="book.html" class="cta">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <svg class="hero-pattern" width="100%" height="160" preserveAspectRatio="none" aria-hidden="true">
          <defs>
            <pattern id="p1" width="40" height="40" patternUnits="userSpaceOnUse">
              <rect width="40" height="40" fill="rgba(235,230,225,0.6)"></rect>
              <circle cx="10" cy="10" r="3" fill="rgba(200,180,165,0.12)"></circle>
              <circle cx="30" cy="30" r="3" fill="rgba(200,180,165,0.12)"></circle>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#p1)"></rect>
        </svg>
        <div class="hero-inner">
          <h1>Invite steadiness in small steps</h1>
          <p class="lead">Practical integrative guidance that layers simple practices, short check-ins, and a three-stage plan to restore ease. Educational and supportive—no medical promises.</p>
          <div class="hero-actions">
            <a id="primary-cta" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">Meet the guide</a>
          </div>
          <div class="contact-inline">Call: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </section>

      <section class="diagnostic" id="diagnostic">
        <h2>How do you feel right now?</h2>
        <p class="muted">Choose one state — the site will suggest a matching path and adjust the next step.</p>
        <div class="mood-grid" role="tablist" aria-label="Mood selector">
          <button class="mood" data-mood="scattered">Scattered</button>
          <button class="mood" data-mood="anxious">Anxious</button>
          <button class="mood" data-mood="drained">Drained</button>
          <button class="mood" data-mood="steady">Steady but seeking growth</button>
        </div>

        <div class="mood-result" id="mood-result">
          <h3 class="method-title">A quiet invitation</h3>
          <p class="method-desc">Select a state to reveal a suggested first practice and a short plan. Educational guidance only.</p>
          <div class="mood-cta">
            <a id="mood-cta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </section>

      <section class="plan" id="plan">
        <h2>Three-phase roadmap</h2>
        <p class="muted">A phased approach to rebuild rhythm. Each stage is illustrative and educational rather than prescriptive.</p>

        <div class="timeline" id="timeline-main">
          <div class="phase" data-phase="1">
            <h4>Phase 1 — Notice & Anchor</h4>
            <p class="phase-body">Micro-practices to ground the day: brief breathing, one sensory pause, gentle movement. Suggested duration: 1–3 weeks.</p>
            <div class="disclaimer">Disclaimer: Informational support only. Consult healthcare providers for clinical concerns.</div>
          </div>
          <div class="phase" data-phase="2">
            <h4>Phase 2 — Build Routine</h4>
            <p class="phase-body">Introduce two steady practices that fit your life. Short coaching check-ins help adapt the rhythm. Suggested duration: 4–8 weeks.</p>
            <div class="disclaimer">Disclaimer: Educational guidance. Not a substitute for medical care.</div>
          </div>
          <div class="phase" data-phase="3">
            <h4>Phase 3 — Integrate & Expand</h4>
            <p class="phase-body">Layer supportive habits, refine pacing, and plan maintenance. Focus on small wins and predictable cues.</p>
            <div class="disclaimer">Disclaimer: This roadmap is illustrative. Personalization is recommended.</div>
          </div>
          <div class="timeline-actions">
            <button class="btn" id="start-plan">Start a guided introduction</button>
          </div>
        </div>

      </section>

      <section class="micro_habits" id="micro_habits">
        <h2>Micro-habits to try today</h2>
        <p class="muted">Tiny moves you can test immediately; each takes under three minutes.</p>
        <ul class="habit-list">
          <li><label><input type="checkbox"> One slow breath + shoulder release</label></li>
          <li><label><input type="checkbox"> Two-minute sensory scan (sight, sound, touch)</label></li>
          <li><label><input type="checkbox"> A short walk heading out with intention</label></li>
        </ul>
        <p class="muted small">Micro-habits are practices to explore — results vary. If you have a health condition, check with your clinician.</p>
      </section>

      <section class="pricing" id="pricing">
        <h2>Offerings & investment</h2>
        <p class="muted">Flexible options framed as supportive learning paths; engagements often begin with an introductory session.</p>
        <div class="packages">
          <div class="package">
            <h3>Seed Rhythm</h3>
            <p class="price">Intro session starting at $95</p>
            <p>Single orientation plus a simple take-away plan to try for two weeks.</p>
            <a class="btn" href="book.html">Reserve an intro</a>
          </div>
          <div class="package recommended">
            <h3>Root Path</h3>
            <p class="price">Short series from $320</p>
            <p>Three sessions across six weeks: notice, practice, and adjust with short check-ins.</p>
            <a class="btn" href="book.html">Begin the path</a>
          </div>
          <div class="package">
            <h3>Evergreen Collaborative</h3>
            <p class="price">Ongoing partnership, monthly starting at $560</p>
            <p>Monthly support with flexible check-ins and periodic review of the plan.</p>
            <a class="btn" href="contact.html">Discuss a plan</a>
          </div>
        </div>

        <div class="timeline secondary" id="timeline-secondary">
          <h4>Another view of the three steps</h4>
          <div class="phase-list">
            <div class="phase-item"><strong>1.</strong> Learn & Notice — small, repeatable cues.</div>
            <div class="phase-item"><strong>2.</strong> Stabilize — make two reliable practices habitual.</div>
            <div class="phase-item"><strong>3.</strong> Maintain & adapt — gentle review and adjustment.</div>
          </div>
          <div class="disclaimer muted">Educational content only. Not clinical advice.</div>
        </div>

      </section>

      <section class="cta" id="final-cta">
        <h2>Ready to try a small, guided step?</h2>
        <p class="muted">Short sessions and clear next actions—easy to fit into a busy day.</p>
        <div class="cta-actions">
          <a id="final-cta-btn" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Ask a question</a>
        </div>
      </section>

    </main>

    <footer class="site-footer">
      <div class="footer-inner">
        <div>{{BUSINESS_NAME}} — gentle integrative guidance • {{CITY}}, {{STATE}}</div>
        <div>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div class="small">This site offers educational information. It is not a substitute for professional medical advice.</div>
      </div>
    </footer>
  </div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
