{"path":"assets/css/styles.css","content":":root{--bg:#FBF9F7;--muted:#6b6b6b;--accent:#B89A8C;--accent-2:#C9B4A6;--card:#fff;--text:#2b2b2b;--radius:10px}*{box-sizing:border-box}html,body{height:100%}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--text);background:var(--bg);line-height:1.4}a{color:inherit;text-decoration:none}img{max-width:100%}page-wrap{display:block}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;background:transparent} .brand{display:flex;gap:12px;align-items:center} .logo svg{display:block} .identity .name{font-weight:700} .identity .tag{font-size:13px;color:var(--muted)}
.nav{display:flex;gap:14px;align-items:center}
.nav a{padding:8px 10px;border-radius:8px;color:var(--muted);font-size:15px}
.nav a.cta{background:var(--accent);color:#fff}
.hero{padding:36px 28px 24px;position:relative;overflow:hidden}
.hero-inner{max-width:980px;margin:0 auto}
.hero h1{font-size:28px;margin:0 0 8px;color:var(--text)}
.lead{color:var(--muted);margin:0 0 16px}
.hero-actions{display:flex;gap:10px;margin:12px 0}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;background:transparent;border:1px solid transparent;cursor:pointer}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.contact-inline{margin-top:12px;color:var(--muted);font-size:14px}
.section-header{padding:24px 28px}
.diagnostic, .plan, .micro_habits, .pricing, .cta{background:transparent;padding:26px 28px;margin-top:12px;border-radius:var(--radius);max-width:980px;margin-left:auto;margin-right:auto}
.diagnostic h2, .plan h2, .micro_habits h2, .pricing h2, .cta h2{margin:0 0 8px}
.muted{color:var(--muted)}
.mood-grid{display:flex;gap:10px;margin:14px 0}
.mood{padding:12px 14px;border-radius:10px;background:#fff;border:1px solid rgba(0,0,0,0.04);cursor:pointer}
.mood:focus{outline:2px solid var(--accent-2)}
.mood-result{background:linear-gradient(180deg,#fff,#f7f4f2);padding:14px;border-radius:10px;margin-top:12px}
.timeline{display:block;background:#fff;padding:14px;border-radius:10px;margin-top:12px;border:1px solid rgba(0,0,0,0.04)}
.phase{padding:10px 0;border-bottom:1px dashed rgba(0,0,0,0.06)}
.phase:last-child{border-bottom:none}
.phase h4{margin:0 0 6px}
.disclaimer{font-size:12px;color:var(--muted);margin-top:8px}
.habit-list{list-style:none;padding:0;margin:12px 0}
.habit-list li{background:#fff;padding:10px;border-radius:8px;margin-bottom:8px;border:1px solid rgba(0,0,0,0.04)}
.packages{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:12px}
.package{background:#fff;padding:14px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
.package.recommended{box-shadow:0 6px 22px rgba(184,154,140,0.08);border-color:var(--accent-2)}
.price{font-weight:700;margin:8px 0}
.site-footer{padding:20px 28px;border-top:1px solid rgba(0,0,0,0.04);margin-top:28px;background:transparent}
.footer-inner{max-width:980px;margin:0 auto;color:var(--muted);display:flex;flex-direction:column;gap:6px}
.small{font-size:12px}
@media(min-width:720px){.hero h1{font-size:34px}.nav a{font-size:15px}}
/* visual anchor: patterned SVG background loader */
.hero-pattern{position:absolute;left:0;top:0;opacity:0.8}
.mood[aria-selected="true"]{background:var(--accent-2);color:#fff}
.timeline-actions{margin-top:12px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mood-to-Method selector
  var moodButtons = document.querySelectorAll('.mood');
  var moodResult = document.getElementById('mood-result');
  var moodCta = document.getElementById('mood-cta');
  var primaryCta = document.getElementById('primary-cta');
  var finalCtaBtn = document.getElementById('final-cta-btn');

  var methods = {
    scattered: {
      title: 'Anchor the attention',
      desc: 'Short, surface-level cues to pull scattered energy into a single line: one minute breath, one visible object focus, and a small movement cue. Try this three times today.',
      ctaLabel: 'Try a 1-minute anchor',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    },
    anxious: {
      title: 'Slow the signal',
      desc: 'Calming pacing techniques: paced breathing, soft orientation to senses, and a brief writing check-in. Educational and supporting—seek clinical assistance for severe anxiety.',
      ctaLabel: 'Book a calming intro',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    },
    drained: {
      title: 'Shift toward replenishment',
      desc: 'Gentle micro-rests and tiny rituals for energy return: micro-movements, hydration cue, and a sensory pause. Not medical advice—adapt to needs.',
      ctaLabel: 'Reserve a short consult',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    },
    steady: {
      title: 'Refine & expand',
      desc: 'If you're steady and seek growth, the focus shifts to pacing increases, safety checks, and adding experiments slowly over weeks.',
      ctaLabel: 'Explore steady options',
      ctaUrl: '{{PRIMARY_CTA_URL}}'
    }
  };

  function selectMood(mood, btn){
    // update visual state
    moodButtons.forEach(function(b){b.setAttribute('aria-selected','false')});
    if(btn) btn.setAttribute('aria-selected','true');
    var m = methods[mood] || {title:'A quiet invitation',desc:'Select a state to reveal a suggested first practice.',ctaLabel:document.querySelector('#primary-cta').textContent,ctaUrl:document.querySelector('#primary-cta').getAttribute('href')};
    moodResult.querySelector('.method-title').textContent = m.title;
    moodResult.querySelector('.method-desc').textContent = m.desc;
    moodCta.textContent = m.ctaLabel;
    moodCta.setAttribute('href', m.ctaUrl);
    // also nudge main CTAs
    primaryCta.textContent = m.ctaLabel;
    finalCtaBtn.textContent = m.ctaLabel;
  }

  moodButtons.forEach(function(btn){
    btn.addEventListener('click', function(e){
      var mood = btn.getAttribute('data-mood');
      selectMood(mood, btn);
      // store recent mood choice
      try{localStorage.setItem('lastMood',mood);}catch(e){}
    });
  });

  // restore last mood if present
  try{
    var last = localStorage.getItem('lastMood');
    if(last){
      var b = document.querySelector('.mood[data-mood="'+last+'"]');
      if(b) selectMood(last,b);
    }
  }catch(e){}

  // Timeline planner: simple interactive checklist
  function wireTimeline(id){
    var el = document.getElementById(id);
    if(!el) return;
    var phases = el.querySelectorAll('.phase');
    phases.forEach(function(p){
      var head = p.querySelector('h4');
      head.style.cursor = 'pointer';
      head.addEventListener('click', function(){
        p.classList.toggle('open');
        if(p.classList.contains('open')) p.style.background = 'linear-gradient(90deg, rgba(200,180,165,0.04), rgba(0,0,0,0.02))';
        else p.style.background='transparent';
      });
    });
    var startBtn = el.querySelector('#start-plan');
    if(startBtn){
      startBtn.addEventListener('click', function(){
        // simulate moving user to booking with context
        window.location = '{{PRIMARY_CTA_URL}}';
      });
    }
  }

  wireTimeline('timeline-main');
  wireTimeline('timeline-secondary');

  // micro-habit checkboxes: small persistence
  var habitChecks = document.querySelectorAll('.habit-list input[type=checkbox]');
  habitChecks.forEach(function(cb, idx){
    var key = 'habit-'+idx;
    try{
      var stored = localStorage.getItem(key);
      if(stored === '1') cb.checked = true;
    }catch(e){}
    cb.addEventListener('change', function(){
      try{localStorage.setItem(key, cb.checked ? '1' : '0');}catch(e){}
    });
  });

  // small accessibility: enable Enter on mood buttons
  moodButtons.forEach(function(b){b.addEventListener('keydown', function(e){ if(e.key === 'Enter') b.click(); })});

})();
"} 
